const paths = [
  "/app/fixture/README.md",
  "/app/fixture/browser-error.txt",
  "/app/fixture/plugin-apply-error.txt",
  "/app/fixture/host-boot-log.txt",
  "/app/fixture/restart-notes.txt",
  "/app/fixture/working-plugin-excerpt.txt",
  "/app/fixture/profile/cordis.patch.yml",
  "/app/fixture/plugin/lib/client.js"
];
const rs = await Promise.all(paths.map(path => tools.exec_command({cmd:`sed -n '1,260p' '${path}'`,workdir:"/app",yield_time_ms:10000,max_output_tokens:12000})));
for (let i=0;i<rs.length;i++) {
  text(`===== ${paths[i]} =====\n${rs[i].output}`);
}

